const input = $input.first().json;
const body = input.body ?? input;
if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error('Heartbeat phải là JSON object.');
if (typeof body.device_id !== 'string' || !body.device_id.trim()) throw new Error('Thiếu device_id.');
return [{json: {
  device_id: body.device_id,
  received_at: new Date().toISOString()
}}];

const response = $input.first().json;
const input = $('Parse Heartbeat').first().json;
const base = {workflow_version: 'V3', branch: 'heartbeat', received_at: input.received_at};
function fail(code, message) {
  return [{json: {...base, success: false, ok: false, http_status: code, device_id: input.device_id, error: message}}];
}
if (response.error || !Number.isInteger(response.statusCode)) return fail(503, 'Không nhận được phản hồi hợp lệ từ backend.');
let result = response.body;
if (typeof result === 'string') {
  try { result = JSON.parse(result); } catch { result = null; }
}
if (response.statusCode < 200 || response.statusCode >= 300) {
  const code = response.statusCode >= 400 && response.statusCode <= 599 ? response.statusCode : 502;
  const message = Array.isArray(result?.message) ? result.message.join(' | ') : typeof result?.message === 'string' ? result.message : 'Backend từ chối heartbeat.';
  return fail(code, message);
}
if (result?.ok !== true || typeof result.device_id !== 'string' || !Number.isFinite(Date.parse(result.last_seen))) return fail(502, 'Backend response không đúng contract heartbeat.');
if (input.device_id !== result.device_id && input.device_id !== result.device_code) return fail(502, 'Backend trả sai thiết bị.');
return [{json: {
  ...base,
  success: true,
  ok: true,
  http_status: 200,
  device_id: result.device_id,
  device_code: result.device_code,
  last_seen: result.last_seen,
  message: 'Backend đã lưu heartbeat.'
}}];

function body(name) {
  const response = $(name).first().json;
  if (!Number.isInteger(response.statusCode) || response.statusCode < 200 || response.statusCode >= 300) throw new Error(name + ': backend response không thành công.');
  return response.body;
}
const offlineAtCheck = body('POST Check Offline');
const expireResult = body('POST Expire Commands');
const allDevices = body('GET All Devices');
if (!Array.isArray(offlineAtCheck)) throw new Error('Check Offline phải trả mảng trong body.');
if (!Array.isArray(allDevices)) throw new Error('GET All Devices phải trả mảng trong body.');
if (!expireResult || !Number.isInteger(expireResult.expired) || expireResult.expired < 0 || !Array.isArray(expireResult.commands) || expireResult.expired !== expireResult.commands.length) throw new Error('Response expire không hợp lệ.');
const checked_at = new Date().toISOString();
const enabled = allDevices.filter(d => d.enabled === true);
const byId = new Map(allDevices.map(d => [d.id, d]));
const online = enabled.filter(d => d.online === true);
const offline = enabled.filter(d => d.online === false);
const incidents = [];
for (const d of offline) {
  incidents.push({
    incident_candidate: true,
    type: 'DEVICE_OFFLINE',
    severity: 'HIGH',
    title: 'Thiết bị mất kết nối: ' + d.code,
    source: 'WF06',
    event_key: 'WF06:OFFLINE:' + d.id + ':' + (d.last_seen ?? 'NEVER_SEEN'),
    dedup_key: 'offline-' + d.id,
    device_id: d.id,
    device_code: d.code,
    room: d.room_code,
    observed_at: checked_at,
    recovered: false,
    details: {
      last_seen: d.last_seen,
      threshold_seconds: 90,
      detected_at: checked_at
    }
  });
}
for (const c of expireResult.commands) {
  const id = c.command_id ?? c.id;
  if (!id || !c.device_id) throw new Error('Expired command thiếu ID.');
  const d = byId.get(c.device_id);
  incidents.push({
    incident_candidate: true,
    type: 'COMMAND_FAILURE',
    severity: 'MEDIUM',
    title: 'Lệnh hết hạn trước khi được xác nhận',
    source: 'WF06',
    event_key: 'WF06:COMMAND_TIMEOUT:' + id,
    dedup_key: 'timeout-' + id,
    device_id: c.device_id,
    device_code: d?.code ?? null,
    room: d?.room_code ?? null,
    command_id: id,
    observed_at: checked_at,
    recovered: false,
    details: {
      event_type: 'COMMAND_TIMEOUT',
      command_id: id,
      new_status: 'TIMED_OUT',
      detected_at: checked_at
    }
  });
}
return [{json: {
  workflow_version: 'V3',
  success: true,
  branch: 'scheduled_check',
  threshold_seconds: 90,
  total_enabled_devices: enabled.length,
  online_count: online.length,
  offline_count: offline.length,
  offline_count_at_initial_check: offlineAtCheck.length,
  online_devices: online.map(d => ({device_id: d.id, device_code: d.code, room: d.room_code, last_seen: d.last_seen})),
  offline_devices: offline.map(d => ({device_id: d.id, device_code: d.code, room: d.room_code, last_seen: d.last_seen})),
  expired_count: expireResult.expired,
  expired_commands: expireResult.commands,
  incidents,
  has_incidents: incidents.length > 0,
  incident_delivery: 'NOT_CONNECTED',
  recovery_tracking: 'NOT_IMPLEMENTED',
  checked_at
}}];

const data = $input.first().json;
const devices = $('GET All Devices').first().json.body;

if (!Array.isArray(devices)) {
  throw new Error('GET All Devices không trả mảng trong body.');
}

return data.incidents.map(incident => {
  const candidate = { ...incident };

  if (candidate.type === 'DEVICE_OFFLINE') {
    const device = devices.find(
      d => d.id === candidate.device_id
    );

    if (!device) {
      throw new Error('Không tìm thấy thiết bị của cảnh báo offline.');
    }

    // Giữ nguyên mốc sự kiện trong cùng một đợt offline.
    const anchor = device.last_seen ?? device.created_at;
    const anchorMs = Date.parse(anchor);

    if (!Number.isFinite(anchorMs)) {
      throw new Error('Thiết bị thiếu last_seen/created_at hợp lệ.');
    }

    const anchorIso = new Date(anchorMs).toISOString();

    // Thiết bị từng kết nối: offline sau 90 giây.
    // Thiết bị chưa từng kết nối: dùng thời điểm tạo thiết bị.
    const observedAt = new Date(
      anchorMs + (device.last_seen ? 90000 : 0)
    ).toISOString();

    candidate.event_key =
      `WF06:OFFLINE:${device.id}:${anchorIso}`;

    candidate.dedup_key = `offline-${device.id}`;
    candidate.observed_at = observedAt;
    candidate.recovered = false;

    // Không đưa thời gian kiểm tra thay đổi mỗi lượt
    // vào nội dung của cùng một sự kiện.
    candidate.details = {
      source: 'WF06',
      last_seen: device.last_seen ?? null,
      offline_since: observedAt,
      threshold_seconds: 90
    };
  }

  delete candidate.incident_delivery;
  delete candidate.message;

  return { json: candidate };
});

const data = $input.first().json;
return [{json: {
  ...data,
  message: 'Không có thiết bị đang bật bị offline trong snapshot cuối; lượt expire này không xử lý thêm lệnh hết hạn. Đây không phải kết luận về toàn bộ lịch sử sự cố.'
}}];

return $input.all().map((item, index) => {
  const result = item.json;

  if (result.ok !== true || result.processed_by !== 'WF10') {
    throw new Error('Flow 10 chưa xác nhận xử lý sự kiện.');
  }

  return {
    json: {
      workflow_version: 'V3',
      incident_delivery: 'CONFIRMED',
      incident_id: result.incident_id,
      event_key: result.event_key,
      event_action: result.event_action,
      event_duplicate: result.event_duplicate,
      status: result.status,
      count: result.count
    },
    pairedItem: { item: index }
  };
});

const response = $input.first().json;
const incidents = response.body;
const health = $('Process Health Results').first().json;

if (response.statusCode !== 200 || !Array.isArray(incidents)) {
  throw new Error('Không lấy được danh sách sự cố.');
}

if (health.success !== true || !Array.isArray(health.online_devices)) {
  throw new Error('Chưa có kết quả kiểm tra thiết bị hợp lệ.');
}

const onlineDevices = new Map(
  health.online_devices.map(device => [device.device_id, device])
);

const results = [];

for (const incident of incidents) {
  // Chỉ xử lý sự cố mất kết nối do WF06 tạo, chưa được đóng.
  if (
    incident.type !== 'DEVICE_OFFLINE' ||
    incident.details?.source !== 'WF06' ||
    incident.status === 'RESOLVED' ||
    incident.resolved_at
  ) {
    continue;
  }

  const device = onlineDevices.get(incident.device_id);
  if (!device) continue;

  const lastSeenMs = Date.parse(device.last_seen);
  const incidentMs = Date.parse(incident.last_seen);
  const nowMs = Date.now();
  const thresholdSeconds = Number(health.threshold_seconds);

  if (
    !Number.isFinite(lastSeenMs) ||
    !Number.isFinite(incidentMs) ||
    !Number.isFinite(thresholdSeconds) ||
    thresholdSeconds <= 0
  ) {
    continue;
  }

  // Phải có tín hiệu mới sau sự cố và vẫn còn trong ngưỡng online.
  if (
    lastSeenMs <= incidentMs ||
    lastSeenMs > nowMs ||
    nowMs - lastSeenMs >= thresholdSeconds * 1000
  ) {
    continue;
  }

  const recoveredAt = new Date(lastSeenMs).toISOString();

  results.push({
    json: {
      workflow_version: 'V3',
      source: 'WF06',
      type: 'DEVICE_OFFLINE',
      severity: incident.severity,
      title: incident.title,
      device_id: incident.device_id,
      device_code: device.device_code,
      room: incident.room_code || device.room,

      // Dùng khóa gốc để backend tìm đúng sự cố.
      dedup_key: `offline-${incident.device_id}`,

      // Gắn với sự cố và thời điểm tín hiệu phục hồi.
      event_key:
        `WF06:RECOVERED:${incident.id}:${recoveredAt}`,

      recovered: true,
      observed_at: recoveredAt,
      details: {
        source: 'WF06',
        incident_id: incident.id,
        last_seen: recoveredAt,
        previous_offline_since:
          incident.details.offline_since || incident.first_seen,
        threshold_seconds: thresholdSeconds
      }
    }
  });
}

// Không có sự cố cần đóng thì nhánh kết thúc tại đây.
return results;
